USE TradingIntelligenceDB;
GO

IF OBJECT_ID('ExecutedTrades', 'U') IS NULL
BEGIN
    CREATE TABLE ExecutedTrades (
        TradeID INT IDENTITY(1,1) PRIMARY KEY,
        Symbol VARCHAR(25) NOT NULL,
        TradeNumber INT NOT NULL,
        Type VARCHAR(15) NOT NULL,
        DataAndTime VARCHAR(50) NULL, 
        OrderID VARCHAR(50) NULL,     
        Signal VARCHAR(15) NOT NULL,
        Price DECIMAL(18, 5) NOT NULL,
        Size_Qty DECIMAL(18, 4) NOT NULL,
        Size_Value DECIMAL(18, 2) NOT NULL,
        Net_PnL_USD DECIMAL(18, 2) DEFAULT 0.00,
        Return_Pct DECIMAL(18, 4) DEFAULT 0.00,
        Commission_USD DECIMAL(18, 2) DEFAULT 0.00,
        Cumulative_PnL_USD DECIMAL(18, 2) DEFAULT 0.00,
        Cumulative_PnL_Pct DECIMAL(18, 4) DEFAULT 0.00
    );
END;
GO

SELECT
   Symbol,
   COUNT(TradeNumber)/2 AS Total_Trades_Executed,
   SUM(Net_PnL_USD) AS Total_Net_Profit_USD,
   AVG(Return_Pct) AS Average_Return_Per_Trade_Pct
FROM ExecutedTrades
GROUP BY Symbol
ORDER BY Total_Net_Profit_USD DESC;
GO

SELECT 
    Symbol,
    SUM(CASE WHEN Net_PnL_USD > 0 AND Type LIKE 'Exit%' THEN 1 ELSE 0 END) AS Winning_Trades,
    SUM(CASE WHEN Net_PnL_USD <= 0 AND Type LIKE 'Exit%' THEN 1 ELSE 0 END) AS Losing_Trades,
    CAST(
        SUM(CASE WHEN Net_PnL_USD > 0 AND Type LIKE 'Exit%' THEN 1 ELSE 0 END) * 100.0 / 
        (COUNT(TradeNumber) / 2) 
    AS DECIMAL(5,2)) AS Win_Rate_Percentage
FROM ExecutedTrades
GROUP BY Symbol;
GO

